mapper.select:
SELECT /* LGVATTCOMM.retrieveAttendanceTypeList */ ac_t.time_and_attendance_type_code AS code /* 근태유형명 */ , lgvhr_common_pkg.decode_lookup('LGVHR_ATTENDANCE_TYPE_CODE', ac_t.time_and_attendance_type_code, NULL, #{USER_SESSION.langaugeCode}) AS name /* 근태유형명 */ FROM tb_att_code_c ac_t /* 근태유형 */ , tb_att_code_c ac_c /* 근태코드 */ WHERE ac_t.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND ac_c.subsidiary_code = ac_t.subsidiary_code AND ac_c.time_and_attendance_type_code = ac_t.time_and_attendance_type_code
AND ac_c.ofc_wrk_tech_wrk_type_code IN ('ALL', #{ofcWrkTechWrkTypeCode})
AND ac_c.gender_code IN ('ALL', #{genderCode})
AND ac_c.use_flag = #{useFlag}
AND ac_c.daily_time_attend_plan_tg_flag = #{planTgFlag}
AND ac_c.daily_time_attend_rslt_tg_flag = #{rsltTgFlag}
GROUP BY ac_t.time_and_attendance_type_code ORDER BY ac_t.time_and_attendance_type_code

SELECT /* LGVATTCOMM.retrieveAttendanceCodeList */ ac.time_and_attendance_code AS code /* 근태코드 */ , ac.time_and_attendance_short_name AS name /* 근태명 */ , ac.time_and_attendance_type_code AS attend_type_name /* 근태유형명 */ , overtime_flag /* 연장근무여부 */ , use_flag /* 사용여부 */ , update_enable_flag /* 수정가능여부 */ , daily_time_attend_plan_tg_flag AS plan_tg_flag /* 일별근태계획대상여부 */ , daily_time_attend_rslt_tg_flag AS rslt_tg_flag /* 일별근태실적대상여부 */ FROM tb_att_code_c ac WHERE ac.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND ac.ofc_wrk_tech_wrk_type_code IN ('ALL', #{ofcWrkTechWrkTypeCode})
AND ac.gender_code IN ('ALL', #{genderCode})
AND ac_c.use_flag = #{useFlag}
AND ac.daily_time_attend_plan_tg_flag = #{planTgFlag}
AND ac.daily_time_attend_rslt_tg_flag = #{rsltTgFlag}
ORDER BY ac.time_and_attendance_type_code, ac.time_and_attendance_short_name, ac.time_and_attendance_code

SELECT /* LGVATTCOMM.retrieveEmployee */ em.employee_number AS employee_no , em.full_name_local AS employee_name , em.grade AS grade_code , em.grade_title ,(SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) as grade_title_name , em.grade_type AS emp_category_name , em.organization_id , um.default_org_id , em.org_name_local AS organization_name , em.attribute10 AS shift_type_code , em.job_family||'.'||em.job_group||'.'||em.job_detail AS work_type_name , em.assignment_category AS employment_category_code /* 재량권 조회시 사용 */ ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , um.application_user_id , um.mail_addr , cv.organization_id AS operating_unit_id , lgvhr_common_pkg.get_org_resp_flag_func(em.subsidiary_code, em.employee_number, TRUNC(SYSDATE)) AS org_resp_flag /* 조직책임자 여부 */ , em.subsidiary_code , um.language_code , em.fse_yn /* FSE 여부 */ , em.flsa_yn /* 단기파견자 여부 */ FROM emp_master em , lgcom_user_m um , lgcom_company_v cv
WHERE em.employee_number = #{USER_SESSION.userName}
WHERE em.employee_number = #{employeeNo}
AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code

SELECT /* LGVATTCOMM.retreiveRequestBasicInfo */ #{requestMasterId} AS request_master_id , cc.common_code AS request_code , #{USER_SESSION.defaultOrgId} AS ou_id , cc_m.parent_common_code||'-'||cc_m.code_data5_value||'-'|| cc.common_code||'-'|| #{requestMasterId, jdbcType=VARCHAR} AS request_no /* LGVHR-모듈3자리-request_code-request_mater_id */ , cc_m.parent_common_code AS system_code , cc.parent_common_code AS module_code , cm.common_code_name AS request_title , cm.common_code_name AS comment_content , #{requestorId} AS requestor_id , NVL(cc_yn.code_data2_value, 'Y') AS portal_flag /* 통합결재 전송할지 여부 */ , NVL(cc_yn.code_data3_value, 'Y') AS mail_flag /* 메일발송여부 */ FROM lgcom_common_code_c cc , lgcom_common_code_multi_lang_c cm , lgcom_common_code_c cc_m /* system_code, module_code 조회하기 위한 모듈코드 */ , lgcom_common_code_c cc_yn /* 통합결재, 메일발송여부 조회하기 위한 코드 */ WHERE cc.code_type_code = 'LGCOM_APPROVAL_REQUEST_CODE'
AND cc.code_data3_value = #{approvalMenuId}
AND cc.common_code = #{requestCode}
AND cc.code_data3_value = #{master.approvalMenuId}
AND cc.common_code = #{master.requestCode}
AND 1=2
AND cm.code_type_code = cc.code_type_code AND cm.common_code = cc.common_code AND cm.language_code = #{USER_SESSION.languageCode} AND cc_m.code_type_code = 'LGCOM_MODULE_CODE' AND cc_m.common_code = cc.parent_common_code
AND cc_yn.code_type_code(+) = 'LGVCOM_APPROVAL_REQUEST_CODE' AND cc_yn.parent_code_type_code(+) = cc.code_type_code AND cc_yn.parent_common_code(+) = cc.common_code

SELECT /* LGVATTCOMM.retrieveCalculateOtParamData */ #{LGVHR_PROJECT_SESSION.subsidiaryCode} AS subsidiary_code , #{attendanceYyyymmdd} AS attendance_yyyymmdd , #{attendanceCode} AS attendance_code , #{shiftTypeCode} AS shift_type_code , #{nightShiftFlag} AS day_night_flag , #{eveningMealFlag} AS dinner_flag , #{workStartTime} AS working_start_time , TO_CHAR(#{tardyHours}) AS lateness , TO_CHAR(#{earlyLeaveHours}) AS leaving_early , TO_CHAR(#{goingOutHours}) AS going_out , TO_CHAR(#{overtimeSumHours}) AS overtime_sum_hours
/* tb_att_ot_validation_n 저장시 필요한 파라메터 */ , #{LGVHR_PROJECT_SESSION.employeeNo} AS employee_no , #{attendanceYyyymmdd} AS att_date , #{shiftTypeCode} AS actual_shift_code , #{attendanceCode} AS actual_attendance_detail , #{nightShiftFlag} AS actual_day_night , #{workStartTime} AS actual_start_tm , #{eveningMealFlag} AS actual_dinner_chk
, #{USER_SESSION.languageCode} AS language_code , lgvhr_common_pkg.decode_lookup('LGVHR_ATT_COMMON_CODE', 'OT_CHECK_FLAG', 'A1', 'en') AS ot_check_flag FROM DUAL
